struct Order { std::int64_t id = 0; std::string name; };

pqxx::work tx{conn};
auto row = tx.exec_params(
    "INSERT INTO orders(name) VALUES($1) RETURNING id", o.name).one_row();
o.id = row[0].as<std::int64_t>();      // identity written back

// later writes target the key, never the business columns:
tx.exec_params("UPDATE orders SET name = $2 WHERE id = $1", o.id, o.name);

